insert into public.thai_l1_catalog (code, error_group, description_th, example, cause_th, remedy, evidence, skill_id) values
  ('TL-TONE-T2AS3', 'TL-TONE', 'ออกเสียง/ฟังแยกเสียง 2 (หยางผิง, เส้นเสียงขึ้น 35) ไม่ถูก โดยขึ้นไม่ชันพอหรือเริ่มที่ระดับต่ำเกิน ทำให้เพี้ยนไปคล้ายเสียง 3 (214). เป็นครึ่งหนึ่งของ ''คู่สับสน 2/3'' ที่งานวิจัยชี้ว่าหนักที่สุด', '麻 má (เสียง2) ↔ 马 mǎ (เสียง3); 十 shí (2) ↔ 是 shì/事; 国 guó ใน 中国 Zhōngguó (2); 谁 shéi (2)', 'ภาษาไทยไม่มีวรรณยุกต์ที่มี contour ตรงกับ 35 เป๊ะ ๆ; เสียงจัตวา (rising) ของไทยเริ่มต่ำและขึ้นช้ากว่า ผู้เรียนถ่ายโอน (transfer) มาใช้กับเสียง 2 ทำให้ช่วงขึ้นไม่คม และเพราะเสียง 3 ก็มี ''ช่วงขึ้นท้าย'' เหมือนกัน สมองจึงจับคู่ 2↔3 สลับกัน', 'ฝึกหูด้วย minimal pair 麻/马, 十/是, พร้อม ''ท่ามือ'': เสียง 2 = ลากมือขึ้นเส้นเดียวชัน ๆ ไม่มีจุดกด; เทียบกับเสียง 3 ที่ต้อง ''กดลงก่อนแล้วค่อยขึ้น''. เน้นให้เริ่มเสียง 2 ที่ระดับกลางแล้วดันขึ้นสูงให้สุด', 'Li, Y. (2016); Rungruang, A. (2017); Zhang & Liu (2020)', (select id from public.skills where code = 'TL-TONE-T2AS3')),
  ('TL-TONE-T3AS2', 'TL-TONE', 'ออกเสียง/ฟังแยกเสียง 3 (สั่งเซิง, ลงแล้วขึ้น 214) โดยละช่วง ''กดลงต่ำตอนต้น'' เหลือแต่ช่วงขึ้น ทำให้เพี้ยน/ถูกเข้าใจเป็นเสียง 2 (35). เป็นทิศทางที่มีหลักฐานเชิงตัวเลขชัดที่สุด (T3→T2)', '马 mǎ (เสียง3) ↔ 麻 má (เสียง2); 老 lǎo ใน 老师 lǎoshī; 你 nǐ; 好 hǎo; 五 wǔ; 九 jiǔ', 'contour แบบ dipping (ลงแล้วขึ้น 214) ไม่มีในภาษาไทย ผู้เรียนย่อเหลือเป็น ''เสียงขึ้น'' ที่ใกล้เสียงจัตวา/เสียง 2 อีกทั้งเมื่อพูดเสียงดังหรือเน้น ระดับเสียง (pitch) ถูกยกสูงขึ้น ยิ่งทำให้เสียง 3 มีลักษณะเหมือนเสียง 2', 'เน้นวลี ''กดต่ำก่อน'' — ฝึกออกเสียง 3 เต็ม (dip ลึก) เฉพาะในคำเดี่ยว/ท้ายประโยค; minimal pair 马/麻, 买 mǎi/埋 mái. ใช้กราฟ pitch แสดงหุบ ''ลง-ขึ้น'' ให้เห็นภาพ', 'Zhang, H. et al. (2025) — ความแม่น T3 76%→66% เมื่อเสียงดัง และการระบุผิด T3 ส่วนใหญ่ถูกจัดเป็น T2; Zhang & Liu (2020); Rungruang, A. (2017)', (select id from public.skills where code = 'TL-TONE-T3AS2')),
  ('TL-TONE-T3HALF', 'TL-TONE', 'ผลิตเสียง 3 ในพยางค์เดี่ยว/ท้ายประโยค ไม่เต็ม contour — ออกเป็น ''ครึ่งเสียงสาม'' (ต่ำล้วน 21 ไม่มีช่วงยกขึ้นท้าย). ต่างจาก TL-TONE-T3AS2 ตรงที่นี่ ''ขาดหางขึ้น'' ไม่ใช่ ''ขาดหัวกด''', '好 hǎo ท้ายประโยค 你好! ; 五 wǔ เมื่อพูดเดี่ยว; 请问 ... 好吗? ที่ 好 อยู่ท้าย', 'ครึ่งเสียงสาม (half-3) เป็นรูปที่ ''ถูก'' เมื่ออยู่หน้าเสียงอื่นที่ไม่ใช่เสียง 3 ผู้เรียนไทยเรียนรูปนี้แล้วนำไปใช้เกินขอบเขต (overgeneralize) กับตำแหน่งเดี่ยว/ท้ายประโยคที่ต้องออก contour เต็ม เพราะภาษาไทยไม่มีเสียง ''ลง-แล้ว-ขึ้น'' ให้ยึด', 'แยกฝึก 2 บริบท: (1) หน้าเสียงอื่น = ออก half-3 ต่ำสั้น; (2) เดี่ยว/ท้ายประโยค = ต้องมีหางขึ้น. ให้ลากเสียง 好~ ท้ายประโยคช้า ๆ เพื่อรู้สึกช่วงยกขึ้น', 'Zhang & Liu (2020) — ''T3 cannot approximate a full falling-rising contour in isolated characters and at sentence-final position''', (select id from public.skills where code = 'TL-TONE-T3HALF')),
  ('TL-TONE-T3SANDHI', 'TL-TONE', 'ไม่แปลงเสียงตามกฎ tone sandhi ของเสียง 3: เมื่อเสียง 3 + เสียง 3 อยู่ติดกัน พยางค์หน้าต้องออกเป็นเสียง 2 (3+3 → 2+3) แต่ผู้เรียนออกเป็น 3+3 ตรงตามพินอินที่เขียน', '你好 nǐ hǎo → อ่าน ní hǎo; 很好 hěn hǎo → hén hǎo; 你有 nǐ yǒu → ní yǒu; 老鼠 lǎo shǔ → láo shǔ', 'เป็นกฎเฉพาะภาษาจีนที่ ''เสียงเขียน ≠ เสียงพูด'' ซึ่งไม่มี pattern ตรงในไทย ผู้เรียนไทยระยะต้นยึดพินอินตามหน้ากระดาษ (เสียง 3 ทั้งคู่) จึงลืมแปลง แม้ไทยจะเป็นภาษาวรรณยุกต์แต่ก็ไม่ช่วยเรื่องกฎ sandhi นี้โดยตรง', 'สอนเป็นกฎชัด ๆ ''3+3 หน้ากลายเป็น 2'' พร้อมคำ HSK1 ที่เจอบ่อย (你好/很好). ฝึกอ่านออกเสียงเป็นคู่ ไม่ใช่ทีละพยางค์', 'กฎ T3 sandhi เป็นสัทศาสตร์จีนมาตรฐาน (ยืนยันได้ทั่วไป เช่น StudyCLI/Hacking Chinese และงาน sandhi acquisition); หมายเหตุ: ยังไม่พบงานวิจัยที่วัด ''อัตราผิด sandhi เฉพาะผู้เรียนไทย'' โดยตรงในรอบค้นนี้ — ตั้ง KC ได้แต่ยังไม่มีตัวเลข Thai-L1 รองรับ', (select id from public.skills where code = 'TL-TONE-T3SANDHI')),
  ('TL-TONE-T4OVER', 'TL-TONE', 'ออกเสียง 4 (ชวี่เซิง, ตกจากสูงลงต่ำ 51) ''ตกช้า/ลากยาว'' เกินไป ไม่ตกคมและสั้นแบบเจ้าของภาษา — เป็นส่วนหนึ่งของอาการ ''สำเนียงต่างชาติทางวรรณยุกต์'' (foreign/洋腔洋调)', '是 shì (4); 四 sì (4) ↔ 十 shí (2); 谢谢 xièxie; 再见 zàijiàn; 不 bù', 'ผู้เรียนถ่ายโอนวรรณยุกต์เอก/โท ของไทยที่มีช่วง pitch แคบกว่าและตกช้ากว่ามาใช้กับเสียง 4 ทำให้ contour การตกไม่ชันและยาวเกิน (ช่วง pitch ของวรรณยุกต์ไทยโดยรวมแคบ/ต่ำกว่าจีนเล็กน้อย)', 'ฝึกให้ตก ''สั้น-คม-เด็ดขาด'' จากสูงสุดลงต่ำสุด เหมือนพูดสั่ง; เทียบยาว-สั้นกับเสียง 2 (ขึ้น) ให้ต่างกันชัด', 'Aroonawongsa, S. et al. (2025) — วิเคราะห์เปรียบเทียบระบบวรรณยุกต์ไทย-จีน และรายงานปรากฏการณ์ ''foreign tone'' ในผู้เรียนไทย; หมายเหตุ: KC นี้มีหลักฐานเชิงคุณภาพ/เปรียบเทียบ แต่ยังไม่มีตัวเลข production เฉพาะเสียง 4 ของคนไทยที่ยืนยันได้ในรอบนี้ — ให้ถ่วงน้ำหนักต่ำกว่าคู่ 2/3', (select id from public.skills where code = 'TL-TONE-T4OVER')),
  ('TL-RETRO-SH-S', 'TL-RETRO', 'ออกเสียง sh [ʂ] (ม้วนลิ้น) เป็น s [s] แบบไทย (ส) — ไม่ม้วนปลายลิ้น ทำให้ 是 shì ฟังเป็น 四 sì, 老师 lǎoshī เป็น ''lǎosī''', '是 shì (เป็น/คือ, HSK1) vs 四 sì (สี่, HSK1); 老师 lǎoshī (ครู, HSK1); 十 shí (สิบ, HSK1) vs 四 sì', 'ภาษาไทยมี /s/ (ส/ซ) แต่ไม่มี retroflex /ʂ/ ผู้เรียนจึงถ่ายโอนไปใช้ /s/ ที่ออกง่ายและมีอยู่แล้วใน L1 เป็นจุดผิดที่มีหลักฐานหนักที่สุดของกลุ่มนี้ (ch/sh ยากสุดใน Suphasa & Chi; ʂ แปรปรวนแต่ s ถูก 100% ใน Kitikanan & Al-Tamimi)', 'ฝึกหูด้วย minimal pair 是/四, 十/四, 山 shān/桑 sāng; สอนวางลิ้น: ม้วนปลายลิ้นแตะปุ่มเหงือกด้านหลัง (เพดานแข็ง) แล้วปล่อยลมเสียดแทรก; ให้จับความรู้สึกต่างกับ ส ไทยที่ปลายลิ้นอยู่หลังฟันล่าง', 'Suphasa & Chi (2017) — sh เป็นพยัญชนะที่ยากที่สุดกลุ่มหนึ่ง; Kitikanan & Al-Tamimi (2012) — retroflex ʂ ออกแปรปรวน ขณะที่ alveolar s ถูก 100% (ไทยหล่นไปใช้ s)', (select id from public.skills where code = 'TL-RETRO-SH-S')),
  ('TL-RETRO-ZH-JZ', 'TL-RETRO', 'ออกเสียง zh [tʂ] เป็น จ /tɕ/ (คล้าย j) หรือแบนเป็น z [ts] — 中国 Zhōngguó ฟังเป็น ''jōngguó/zōngguó'', 找 zhǎo เป็น 早 zǎo', '中国 Zhōngguó (ประเทศจีน, HSK1); 这 zhè (นี่, HSK1); 找 zhǎo (หา, HSK2) vs 早 zǎo (เช้า, HSK1)', 'ไทยไม่มี retroflex affricate /tʂ/ ผู้เรียนแทนด้วย จ /tɕ/ (เสียงที่ใกล้สุดใน L1) หรือแบนไปเป็น z ตามคู่ 平舌 เพราะแยก 翘舌/平舌 ไม่ออก', 'ฝึก minimal pair 找/早, 这/... ; ให้ออก จ ไทยก่อนแล้ว ''ม้วนปลายลิ้นถอยหลัง'' เพื่อเทียบความต่าง; drill คู่ 平舌(z)-翘舌(zh) สลับกันเพื่อสร้าง contrast', 'Suphasa & Chi (2017) — zh อยู่ในชุดพยัญชนะที่เป็นปัญหา; Cai & Lee (2015) — ไทยไม่มีชุด retroflex จึงเกิด transfer; Ma Yue (2017) — ผู้เริ่มต้นไทยมัก ''ยุบ'' zh/ch/sh เป็นเสียงเดียว', (select id from public.skills where code = 'TL-RETRO-ZH-JZ')),
  ('TL-RETRO-CH-CQ', 'TL-RETRO', 'ออกเสียง ch [tʂʰ] เป็น ช /tɕʰ/ (คล้าย q) หรือแบนเป็น c [tsʰ] — 吃 chī ฟังเป็น ''qī/cī'', 茶 chá เป็น ''cá''', '吃 chī (กิน, HSK1); 茶 chá (ชา, HSK1); 出 chū (ออก, HSK2); เทียบ 吃 chī vs 七 qī (เจ็ด, HSK1) เพื่อกัน ch→q', 'ไทยไม่มี retroflex aspirated affricate /tʂʰ/ ผู้เรียนแทนด้วย ช /tɕʰ/ (ใกล้สุดใน L1) หรือแบนเป็น c; เป็นคู่กับ zh แต่แยกออกมาเพราะจุดออกเสียง/การพ่นลมต่างและ ch ยากเป็นพิเศษในข้อมูลไทย', 'minimal pair 吃/七 (ch/q), 茶/... ; เน้นทั้งการม้วนลิ้นและการพ่นลมแรง (aspiration) พร้อมกัน; ฝึกคู่ 平舌 c – 翘舌 ch สลับ', 'Suphasa & Chi (2017) — ระบุชัดว่า ch (ร่วมกับ sh) ยากที่สุดในกลุ่ม retroflex; Ma Yue (2017) — zh/ch/sh มักถูกออกเป็นเสียงเดียวกัน', (select id from public.skills where code = 'TL-RETRO-CH-CQ')),
  ('TL-RETRO-R-L', 'TL-RETRO', 'ออกเสียง r [ʐ]/[ɻ] (ม้วนลิ้น) เป็น ล /l/ หรือ ร ไทย (รัว/tap) — 热 rè ฟังเป็น ''lè'', 人 rén เป็น ''lén'', 日 rì เป็น ''lì''', '热 rè (ร้อน, HSK1); 人 rén (คน, HSK1); 认识 rènshi (รู้จัก, HSK1); 日 rì (วัน, ใน 生日 shēngrì วันเกิด HSK2)', 'ไทยมี /r/ (ร รัว/tap) และ /l/ ซึ่งต่างจาก Mandarin r ที่เป็น retroflex approximant/fricative ผู้เรียนจึงแทนด้วย ล หรือ ร ไทย ได้ผลเป็นเสียง ''กึ่ง r กึ่ง l'' ที่ไม่ใช่ retroflex; ยิ่งไทยสลับ ร/ล ในชีวิตประจำวันอยู่แล้ว ยิ่งเสริมความสับสน', 'ฝึกหูแยก r/l ด้วยคู่ 热/乐, 人/... ; สอนออก r แบบไม่รัวลิ้น — ค้างปลายลิ้นม้วนใกล้เพดานแข็ง(ตำแหน่งเดียวกับ sh แต่ก้อง/เสียงลากยาว); ห้ามแตะเป็น ล', 'Cai & Lee (2015) — contrastive analysis ชี้ว่าไทยไม่มี Mandarin retroflex r; Ma Yue (2017) — ผู้เรียนไทยออก r เป็นเสียงระหว่าง r จีนกับ l ไทย; Suphasa & Chi (2017) — r อยู่ในชุดพยัญชนะที่เป็นปัญหา', (select id from public.skills where code = 'TL-RETRO-R-L')),
  ('TL-RETRO-FLAT-MERGE', 'TL-RETRO', 'แยก ''เสียงม้วนลิ้น'' (翘舌 zh/ch/sh) กับ ''เสียงไม่ม้วนลิ้น'' (平舌 z/c/s) ไม่ออก ทั้งการฟังและการสะกดพินอิน — สลับ/ยุบเป็นเสียงเดียว เช่น 四 sì ↔ 十 shí, 早 zǎo ↔ 找 zhǎo', 'คู่ทดสอบการฟัง/สะกด: 四 sì (สี่) vs 十 shí (สิบ); 早 zǎo (เช้า) vs 找 zhǎo (หา); 三 sān vs 山 shān', 'เพราะไทยไม่มี retroflex เลย ผู้เรียนจึงไม่มี ''หมวดเสียง'' (phonemic category) สำหรับแยก 翘舌/平舌 — เป็นปัญหาระดับการรับรู้ (perception) ที่อยู่เบื้องหลังจุดผิด SH/ZH/CH ทั้งหมด และเป็นสาเหตุของ fossilization', 'ฝึกงาน AX/AB discrimination ด้วยชุด minimal pair 平舌–翘舌 ก่อนฝึกออกเสียง; ไล่ระดับจาก ''ต่างกันชัด'' ไปหา ''คู่ยาก''; เมื่อหูแยกได้แล้วค่อยโยงไปการสะกดพินอินและการออกเสียง', 'Kitikanan & Al-Tamimi (2012) — retroflex ʂ/ɕ แปรปรวน (ไม่มีหมวดเสียงใน L1); Ma Yue (2017) — ผู้เรียนไทยมัก ''ยุบ zh/ch/sh เป็นเสียงเดียว'' และไม่แยก平/翘舌; Suphasa & Chi (2017) — fossilization ของจุดผิดชุดนี้', (select id from public.skills where code = 'TL-RETRO-FLAT-MERGE')),
  ('TL-GRAM-DE-ORDER', 'TL-GRAM', 'วางส่วนขยาย (คุณศัพท์/แสดงความเป็นเจ้าของ) + 的 ผิดตำแหน่ง คือเอาไปไว้ ''หลัง'' คำนามแบบไทย แทนที่จะไว้ ''หน้า'' คำนาม เช่น พูด 书我的 / 衣服红色的 แทน 我的书 / 红色的衣服', 'ถูก: 我的书 wǒ de shū (หนังสือของฉัน) · 红色的衣服 hóngsè de yīfu (เสื้อสีแดง) · 老师的车 lǎoshī de chē. ผิดแบบไทย: 书我的 / 衣服红色 / 车老师的', 'ภาษาไทยวางส่วนขยายไว้ ''หลัง'' คำนาม (หนังสือของฉัน, เสื้อสีแดง, ครูที่ดี) แต่ภาษาจีนวางไว้ ''หน้า'' คำนามและต้องมีตัวเชื่อม 的 → ผู้เรียนถ่ายโอนลำดับ ''คำนาม + ขยาย'' ของไทยมาตรงๆ', 'สอนสูตร ''ส่วนขยาย + 的 + คำหลัก (ของใคร/สีอะไร/แบบไหน ต้องมาก่อนเสมอ)''; ท่องคู่เทียบไทย↔จีน (ของฉัน→我的…, สีแดง→红色的…); ฝึกลากบล็อกเรียงคำและเน้นว่า 的 เชื่อมส่วนขยายเข้ากับคำนาม', 'Zhang Chujuan (2023) 定语语序 ผู้เรียนไทย; ฐานทฤษฎีถ่ายโอน Cai & Lee (2015)', (select id from public.skills where code = 'TL-GRAM-DE-ORDER')),
  ('TL-GRAM-MW', 'TL-GRAM', 'ข้อผิดวลีลักษณนาม 3 แบบ: (ก) เรียงลำดับผิด — จีนใช้ จำนวน+ลักษณนาม+นาม (三本书) แต่ผู้เรียนเรียงตามไทย นาม+จำนวน+ลักษณนาม; (ข) เลือกลักษณนามผิด/ใช้ 个 พร่ำเพรื่อแทนตัวที่ถูก; (ค) ละลักษณนาม', 'ถูก: 一个人 yí ge rén · 三本书 sān běn shū · 两只猫 liǎng zhī māo. ผิด: 三个书 (个 แทน 本) / 书三本 (เรียงแบบไทย) / 三书 (ละลักษณนาม)', 'ไทยเรียง ''คำนาม + จำนวน + ลักษณนาม'' (หนังสือสามเล่ม, คนหนึ่งคน) ต่างจากจีนที่เรียง ''จำนวน + ลักษณนาม + คำนาม''; และระบบลักษณนามไทย↔จีนไม่จับคู่ตรงตัว → ผู้เรียนเดาผิดหรือใช้ 个 คลุมทุกคำ', 'จับคู่คำนามยอดฮิต HSK1-2 กับลักษณนามเฉพาะ (书→本, 人→个/位, 猫狗→只, 水→杯/瓶); ฝึกสูตร 数+量+名; เตือน ''กับดัก 个'' ว่าไม่ใช้ได้ทุกคำ', 'Kongkamnerd (2024) ข้อผิด 个; Li & Imsamran (2021) ลักษณนามสัตว์; Huang & Funoi (2024) การละลักษณนาม', (select id from public.skills where code = 'TL-GRAM-MW')),
  ('TL-GRAM-COMPL', 'TL-GRAM', 'บทเสริม (补语) — วางผิดตำแหน่ง / ละ / เลือกผิด โดยเฉพาะบทเสริมระดับ V+得+adj (说得很好) และบทเสริมผล V+result (听懂, 吃完)', 'ถูก: 说得很好 shuō de hěn hǎo (พูดได้ดี) · 听懂了 tīng dǒng le (ฟังเข้าใจ) · 吃完了 chī wán le (กินเสร็จ). ผิด: 说很好 / 很好说 / 听了懂', 'ไทยไม่มีโครงสร้าง ''บทเสริม'' แบบจีนตรงๆ (ใช้กริยาเรียงหรือคำวิเศษณ์ธรรมดา ''พูดเก่ง/พูดได้ดี'') → ผู้เรียนละ 得 หรือเอาคำวิเศษณ์ไปไว้หน้ากริยาแบบไทย (很好说) แทน 说得很好', 'สอนแม่แบบ ''กริยา + 得 + ระดับ (说得好/说得很快)'' และ ''กริยา + ผล (懂/完/到)''; เทียบไทย ''พูดได้ดี → 说得好''; ฝึกเติม 得; ใช้ชุดคู่ขั้นต่ำ 说好 vs 说得好 ให้เห็นความต่าง', 'Pichaichanlert (2022) ข้อผิดบทเสริมผลของผู้เรียนไทย ม.ปลาย (พบผิดหลายแบบ: ใช้ผิดตัว/วางผิด/เลี่ยง/ผิดบริบท — หมายเหตุ: ไม่ยืนยันตัวเลข 48%)', (select id from public.skills where code = 'TL-GRAM-COMPL')),
  ('TL-GRAM-LE', 'TL-GRAM', 'ใช้คำช่วย 了 (le) ผิด — ใส่พร่ำเพรื่อ / ละ / วางผิดตำแหน่ง เพราะจับคู่ 了 = ''แล้ว'' แบบตรงตัวทุกครั้ง', 'ถูก: 我吃了饭 wǒ chī le fàn · 他来了 tā lái le · 太贵了 tài guì le. ผิด (ใส่เกินตามบริบท): 我是学生了 / 我很累了 (เมื่อบริบทไม่ได้บ่งการเปลี่ยนสถานะ)', 'ไทยมี ''แล้ว'' ที่คล้าย 了 แต่ความหมาย/หน้าที่ไม่ตรงกัน (แล้ว ครอบคลุมกว้างกว่าและเงื่อนไขต่าง) → ผู้เรียนแมป แล้ว→了 ทุกครั้งที่เหตุการณ์จบ ทำให้ใส่ 了 เกินหรือวางผิดที่', 'เน้นว่า 了 ≠ แล้ว เสมอ; สอน 了 เฉพาะเหตุการณ์ที่เกิดขึ้น/เปลี่ยนสถานะ; ให้ประโยคคู่ ''มี 了 / ไม่มี 了'' พร้อมบริบทให้ตัดสิน', 'Hao, Duan & Yan (2022) Brain Sciences — ผู้เรียน L1 ไทยประมวลผล 了 ต่างจากเจ้าของภาษา และชี้ว่า ''แล้ว''≠''了'' (หมายเหตุ: เป็นงาน ERP/processing ไม่ใช่ error corpus)', (select id from public.skills where code = 'TL-GRAM-LE')),
  ('TL-GRAM-ADV', 'TL-GRAM', 'วางคำวิเศษณ์/ส่วนขยายกริยา (状语) ผิดตำแหน่ง — จีนวางไว้ ''หน้ากริยา'' (也/都/常常/在+สถานที่) แต่ผู้เรียนวางตามลำดับไทย', 'ถูก: 我也是学生 wǒ yě shì xuésheng · 我们都很好 dōu · 我在家吃饭 zài jiā chī fàn. ผิด: 我是也学生 / 我吃饭在家', 'การเรียงส่วนขยายกริยาไทย↔จีนไม่ตรงกัน (เช่น สถานที่/ความถี่มักตามหลังกริยาในไทย) → ถ่ายโอนลำดับไทย ทำให้วางผิด (misordering เป็นหมวดข้อผิดที่พบและโยงกับ L1 negative transfer)', 'สอนกฎ ''状语 (也/都/在…) มาก่อนกริยาเสมอ''; ฝึกเรียงประโยคที่มี 也/都/在+สถานที่; เทียบไทย ''กินข้าวที่บ้าน → 在家吃饭''', 'Zhang Shuaishuai, Thaveewatanaseth & Numtong (2026) — พบข้อผิด ''misordering'' จาก L1 negative transfer ในผู้เรียนไทย (กรณี 就是); ฐานถ่ายโอน Cai & Lee (2015)', (select id from public.skills where code = 'TL-GRAM-ADV'))
